import { type ChangeEvent, type FormEvent, type ReactNode, createContext, useContext, useState } from 'react';
import {
  AlertCircle, ArrowLeft, ArrowRight, BarChart3, Bell, CalendarDays, Check, ChevronRight,
  CircleCheck, Clock3, FileCheck2, FileText, History, LayoutDashboard, ListChecks,
  LockKeyhole, Menu, Settings2, ShieldCheck, Sparkles, Upload, UserRound, UsersRound,
  X, SlidersHorizontal, Building2, ScrollText, Activity, Search, Plus, Eye, CheckCircle2,
} from 'lucide-react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';
import { Link, Route, Switch, useLocation, Router as WouterRouter } from 'wouter';

const queryClient = new QueryClient();
type Role = 'business' | 'department' | 'admin';
type AppStatus = 'Under Review' | 'Action Required' | 'Approved' | 'Inspection Scheduled';

type AppData = {
  applicationStatus: AppStatus;
  setApplicationStatus: (status: AppStatus) => void;
  querySent: boolean;
  setQuerySent: (value: boolean) => void;
  inspectionSlot: string;
  setInspectionSlot: (value: string) => void;
  toast: (message: string) => void;
};
const AuthContext = createContext<{ role: Role | null; setRole: (role: Role | null) => void }>({ role: null, setRole: () => undefined });
const DataContext = createContext<AppData | null>(null);
const useAuth = () => useContext(AuthContext);
const useData = () => {
  const data = useContext(DataContext);
  if (!data) throw new Error('Paper Jam data context is missing');
  return data;
};

const businessNav = [
  ['Home', '/dashboard', LayoutDashboard], ['Approvals', '/approvals', FileCheck2],
  ['Applications', '/applications', FileText], ['Compliance', '/compliance', ShieldCheck], ['Profile', '/profile', UserRound],
] as const;
const departmentNav = [
  ['Dashboard', '/officer', LayoutDashboard], ['Applications', '/officer/applications', FileText],
  ['Inspections', '/officer/inspections', CalendarDays], ['SLA Monitor', '/officer/sla', Clock3],
  ['Analytics', '/officer/analytics', BarChart3], ['Profile', '/officer/profile', UserRound],
] as const;
const adminNav = [
  ['Dashboard', '/admin', LayoutDashboard], ['Departments', '/admin/departments', Building2],
  ['Users', '/admin/users', UsersRound], ['Regulations', '/admin/regulations', ScrollText],
  ['Analytics', '/admin/bottlenecks', BarChart3], ['Audit', '/admin/audit', History], ['Settings', '/admin/settings', Settings2],
] as const;

function Logo() { return <Link href="/" className="brand" data-testid="link-logo">PAPER JAM</Link>; }

function Shell({ children, landing = false, role }: { children: ReactNode; landing?: boolean; role?: Role }) {
  const [location] = useLocation();
  const nav = role === 'department' ? departmentNav : role === 'admin' ? adminNav : businessNav;
  return <div className="paper-app"><div className="shell">
    <header className="topbar">
      <div className="topbar__left"><Logo />
        {!landing && <nav className="pill-nav" aria-label="Primary navigation">{nav.map(([label, href, Icon]) =>
          <Link key={href} href={href} className={location === href ? 'active' : ''} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={13} />{label}</Link>)}</nav>}
        {landing && <nav className="pill-nav landing-links"><a href="#how-it-works">Home</a><a href="#businesses">For Businesses</a><a href="#departments">For Departments</a><a href="#admin">For Admin</a></nav>}
      </div>
      <div className="topbar__right">
        {landing ? <><Link href="/login" className="button button--light" data-testid="link-login">Log in</Link><Link href="/signup" className="button button--dark" data-testid="link-get-started">Get started <ArrowRight size={14} /></Link></> :
          <><Link href={role === 'business' ? '/new-application' : role === 'department' ? '/officer/applications' : '/admin'} className="button button--dark top-cta" data-testid="link-primary-cta">{role === 'business' ? <><Plus size={14} /> New application</> : role === 'department' ? <>Review queue <ArrowRight size={14} /></> : <>Platform pulse <ArrowRight size={14} /></>}</Link><button className="icon-button" aria-label="Notifications" data-testid="button-notifications" onClick={() => window.alert('You are all caught up.')}><Bell size={15} /></button><Link href={role === 'admin' ? '/admin/profile' : role === 'department' ? '/officer/profile' : '/profile'} className="profile-chip" data-testid="link-profile-chip"><span className="avatar">{role === 'admin' ? 'PJ' : role === 'department' ? 'OP' : 'AR'}</span><span>{role === 'admin' ? 'Paper Jam admin' : role === 'department' ? 'Officer Patel' : 'Arjun Rao'}</span></Link></>}
      </div>
    </header>
    {children}
    {!landing && <nav className="mobile-nav" aria-label="Mobile navigation">{nav.slice(0, 4).map(([label, href, Icon]) => <Link key={href} href={href} className={location === href ? 'active' : ''} data-testid={`mobile-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={17} />{label}</Link>)}</nav>}
  </div></div>;
}

function PageIntro({ eyebrow, title, copy, children }: { eyebrow?: string; title: string; copy?: string; children?: ReactNode }) {
  return <div className="page-intro">{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1 className="page-title">{title}</h1>{copy && <p>{copy}</p>}{children}</div>;
}
function Unauthorized() { return <Shell><main className="page center narrow-page"><div className="surface pad auth-message"><LockKeyhole size={27} /><span className="eyebrow">Permission required</span><h1 className="page-title">You don't have access to this area.</h1><p>This workspace is reserved for another Paper Jam role.</p><Link href="/" className="button button--dark" data-testid="link-return-home">Return Home <ArrowRight size={14} /></Link></div></main></Shell>; }
function RoleGate({ allowed, children }: { allowed: Role; children: ReactNode }) { return <RoleGateInner allowed={allowed}>{children}</RoleGateInner>; }
function RoleGateInner({ allowed, children }: { allowed: Role; children: ReactNode }) { const { role } = useAuth(); return role === allowed ? <>{children}</> : <Unauthorized />; }

function Home() {
  const roles = [
    { id: 'business', anchor: 'businesses', title: 'For Businesses', headline: 'Start your application.', body: 'Discover approvals. Prepare documents. Track applications. Stay compliant.', href: '/signup', action: 'Start application', icon: FileText },
    { id: 'department', anchor: 'departments', title: 'For Departments', headline: 'Process approvals without the bottleneck.', body: 'Review applications. Manage queries. Schedule inspections. Track SLAs.', href: '/login?role=department', action: 'Department login', icon: ListChecks },
    { id: 'admin', anchor: 'admin', title: 'For Admin', headline: 'See the bigger picture.', body: 'Manage regulations. Monitor departments. Track bottlenecks. Manage users.', href: '/login?role=admin', action: 'Admin login', icon: Activity },
  ];
  return <Shell landing><main className="page hero-page center" id="how-it-works">
    <span className="eyebrow">Approval intelligence, without the maze</span><h1 className="hero-title">Unjam Your<br />Approval Process.</h1>
    <p className="hero-copy">From discovering approvals to staying compliant,<br />Paper Jam brings the entire journey into one place.</p>
    <div className="hero-actions"><Link href="/signup" className="button button--dark" data-testid="link-start-application">Start your application <ArrowRight size={15} /></Link><a href="#businesses" className="button button--light" data-testid="link-explore">Explore how it works</a></div>
    <div className="hero-stage"><div className="hero-orbit"><span>clear<br />to go</span></div><div className="floating-card"><small>Approval Passport</small><strong><Check size={12} /> 12 verified documents</strong></div><div className="floating-card"><small>Application</small><strong>Food Safety Licence<br /><span className="status status--green">Ready to submit</span></strong></div><div className="floating-card"><small>SLA</small><strong><Clock3 size={12} /> 2 days remaining</strong></div><div className="floating-card"><small>Compliance</small><strong>Renewal due in 18 days</strong></div></div>
    <section className="role-cards" id="businesses">{roles.map(({ id, anchor, title, headline, body, href, action, icon: Icon }) => <article className={`role-card role-card--${id}`} id={anchor} key={id}><div className="role-card__top"><span className="micro">{title}</span><Icon size={18} /></div><h2>{headline}</h2><p>{body}</p><Link href={href} className="button button--dark" data-testid={`link-role-${id}`}>{action} <ArrowRight size={14} /></Link></article>)}</section>
    <div className="feature-strip"><span>Discover</span><span>Prepare</span><span>Submit</span><span>Track</span><span>Comply</span></div>
  </main></Shell>;
}

function Login() {
  const [, setLocation] = useLocation(); const { setRole } = useAuth(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [chooser, setChooser] = useState(false); const [remember, setRemember] = useState(true);
  const params = new URLSearchParams(window.location.search); const suggested = params.get('role') as Role | null;
  const submit = (role: Role) => { setRole(role); setLocation(role === 'business' ? '/dashboard' : role === 'department' ? '/officer' : '/admin'); };
  return <Shell landing><main className="page auth-page"><section className="auth-copy"><span className="eyebrow">Paper Jam / Access</span><h1 className="page-title">Welcome back.</h1><p>Continue where you left off.</p><div className="soft-glow auth-glow"><span className="micro">One product, three clear journeys</span><div className="auth-journey"><span>Discover</span><ArrowRight size={14} /><span>Decide</span><ArrowRight size={14} /><span>Move forward</span></div></div></section><section className="surface pad auth-card"><span className="micro">Secure workspace</span><h2>Log in to Paper Jam</h2><form className="form-stack" onSubmit={(e) => { e.preventDefault(); setChooser(true); }}><div className="field"><label>Email</label><input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@company.com" data-testid="input-login-email" /></div><div className="field"><label>Password</label><input required type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter your password" data-testid="input-login-password" /></div><div className="auth-options"><label className="check-label"><input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} data-testid="input-remember" /> Remember me</label><button type="button" className="text-button" onClick={() => window.alert('Password reset instructions would be sent here.')} data-testid="button-forgot-password">Forgot password?</button></div><button className="button button--dark" type="submit" data-testid="button-login">Log in <ArrowRight size={14} /></button></form><div className="divider"><span>OR</span></div><button className="button button--light full-button" onClick={() => setChooser(true)} data-testid="button-google-login">Continue with Google</button><div className="auth-foot">New to Paper Jam? <Link href="/signup" data-testid="link-create-account">Create an account</Link></div>{chooser && <div className="demo-picker"><div className="demo-picker__head"><div><span className="micro">Demo access</span><h3>Where should we take you?</h3></div><button className="icon-button" onClick={() => setChooser(false)} aria-label="Close demo picker" data-testid="button-close-demo-picker"><X size={15} /></button></div><p>Choose a role for this local product tour. No account is required.</p><div className="demo-role-grid">{(['business', 'department', 'admin'] as Role[]).map((role) => <button key={role} className={`demo-role demo-role--${role} ${suggested === role ? 'selected' : ''}`} onClick={() => submit(role)} data-testid={`button-demo-${role}`}><strong>{role === 'business' ? 'Business' : role === 'department' ? 'Department' : 'Admin'}</strong><span>{role === 'business' ? 'Business dashboard' : role === 'department' ? 'Officer workspace' : 'Platform overview'}</span><ArrowRight size={14} /></button>)}</div></div>}</section></main></Shell>;
}

function Signup() {
  const [, setLocation] = useLocation(); const { setRole } = useAuth(); const [form, setForm] = useState({ name: '', email: '', password: '', confirm: '' }); const [role, setSignupRole] = useState<Role>('business'); const [error, setError] = useState('');
  const update = (key: keyof typeof form) => (e: ChangeEvent<HTMLInputElement>) => setForm({ ...form, [key]: e.target.value });
  const submit = (e: FormEvent) => { e.preventDefault(); if (form.password !== form.confirm) { setError('Passwords need to match.'); return; } setRole(role); setLocation(role === 'business' ? '/onboarding' : role === 'department' ? '/officer' : '/admin'); };
  return <Shell landing><main className="page auth-page signup-page"><section className="auth-copy"><span className="eyebrow">Paper Jam / Begin</span><h1 className="page-title">Create your Paper Jam account.</h1><p>Set up your account and start unjamming your approval process.</p><div className="passport mini-passport"><div className="passport__top"><span>Paper Jam / Passport</span><span>New</span></div><h3>{form.name || 'Your workspace'}.</h3><p>{role === 'business' ? 'Discover · Prepare · Track' : role === 'department' ? 'Receive · Review · Approve' : 'Monitor · Manage · Improve'}</p></div></section><section className="surface pad auth-card"><span className="micro">Create account</span><h2>Your details</h2><form className="form-stack" onSubmit={submit}><div className="field"><label>Full Name</label><input required value={form.name} onChange={update('name')} placeholder="Arjun Rao" data-testid="input-signup-name" /></div><div className="field"><label>Email</label><input required type="email" value={form.email} onChange={update('email')} placeholder="you@company.com" data-testid="input-signup-email" /></div><div className="form-grid"><div className="field"><label>Password</label><input required type="password" value={form.password} onChange={update('password')} data-testid="input-signup-password" /></div><div className="field"><label>Confirm Password</label><input required type="password" value={form.confirm} onChange={update('confirm')} data-testid="input-signup-confirm" /></div></div><div className="field"><label>I am signing up as</label><div className="role-select">{(['business', 'department', 'admin'] as Role[]).map((item) => <button type="button" className={`role-option ${role === item ? 'selected' : ''}`} key={item} onClick={() => { setSignupRole(item); setError(''); }} data-testid={`button-signup-role-${item}`}><strong>{item[0].toUpperCase() + item.slice(1)}</strong><span>{item === 'business' ? 'Available' : item === 'department' ? 'Organization-based' : 'System-created'}</span></button>)}</div></div>{role === 'admin' && <div className="callout callout--purple"><ShieldCheck size={18} /><div><h3>Admin accounts are created by the system administrator.</h3><p>This demo lets you preview the admin experience.</p></div></div>}{error && <p className="form-error">{error}</p>}<button className="button button--dark" type="submit" data-testid="button-create-account">Create account <ArrowRight size={14} /></button></form><div className="auth-foot">Already have an account? <Link href="/login" data-testid="link-login-existing">Log in</Link></div></section></main></Shell>;
}

function Dashboard() { return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Tuesday, 22 September 2026" title="Good morning, ABC Foods." copy="Here’s what needs your attention. You’re closer than it feels." /><section className="soft-glow surface pad"><div className="section-head"><div><span className="micro">Your approval journey</span><h2>6 of 8 approvals completed</h2></div><Link href="/approvals" className="button button--light" data-testid="link-view-roadmap">View roadmap <ArrowRight size={14} /></Link></div><div className="progress-track"><div className="progress-fill" style={{ width: '75%' }} /></div><div className="metric-row"><span>Journey started 12 Sep 2026</span><strong>75%</strong></div></section><div className="stats-grid" style={{ marginTop: '1rem' }}><Link href="/approvals" className="surface stat hoverable" data-testid="card-dashboard-approvals"><span className="micro">Approval roadmap</span><h3>8</h3><p><b>6 completed</b></p></Link><Link href="/applications" className="surface stat hoverable" data-testid="card-dashboard-applications"><span className="micro">Applications</span><h3>3</h3><p><b>active</b></p></Link><Link href="/compliance" className="surface stat hoverable" data-testid="card-dashboard-compliance"><span className="micro">Compliance</span><h3>2</h3><p><b>upcoming</b></p></Link><Link href="/applications" className="surface stat hoverable" data-testid="card-dashboard-sla"><span className="micro">SLA</span><h3>1</h3><p><span className="status status--red">At risk</span></p></Link></div><div className="layout" style={{ marginTop: '2.2rem' }}><section className="surface pad"><span className="micro">Next best action</span><h2>Make your Food Safety application ready.</h2><p className="muted-copy">One signature is keeping your strongest application from moving forward.</p><Link href="/readiness" className="button button--dark" data-testid="link-next-action">Check readiness <ArrowRight size={14} /></Link></section><section className="surface pad"><span className="micro">Recent activity</span><h2>Moving nicely.</h2><div className="check-list"><div className="check-row"><span>Building Approval</span><span className="status status--green">Approved</span></div><div className="check-row"><span>Factory Licence</span><span className="status">In progress</span></div><div className="check-row"><span>Factory layout query</span><span className="status status--amber">Action needed</span></div></div></section></div></main></Shell></RoleGate>; }

function Onboarding() { const [form, setForm] = useState({ name: 'ABC Foods Pvt. Ltd.', sector: 'Food processing', location: 'Gujarat', type: 'Private company' }); const [, setLocation] = useLocation(); return <RoleGate allowed="business"><Shell role="business"><main className="page layout"><section><Link href="/dashboard" className="eyebrow" data-testid="link-onboarding-back"><ArrowLeft size={14} /> Business dashboard</Link><PageIntro eyebrow="01 / 04 · Business" title="Tell us about your business." copy="We’ll use this information to identify the approvals that apply to you." /><div className="surface pad form-stack"><div className="form-grid">{Object.entries({ name: 'Business name', type: 'Business type', sector: 'Sector', location: 'Location' }).map(([key, label]) => <div className="field" key={key}><label>{label}</label>{key === 'type' || key === 'sector' ? <select value={form[key as keyof typeof form]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} data-testid={`select-${key}`}><option>{key === 'type' ? 'Private company' : 'Food processing'}</option><option>{key === 'type' ? 'Partnership' : 'Technology services'}</option></select> : <input value={form[key as keyof typeof form]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} data-testid={`input-${key}`} />}</div>)}</div><div className="form-footer"><Link href="/dashboard" className="button button--light" data-testid="button-onboarding-back">Back</Link><button className="button button--dark" onClick={() => setLocation('/dashboard')} data-testid="button-onboarding-continue">Continue <ArrowRight size={14} /></button></div></div></section><aside className="soft-glow"><div className="passport"><div className="passport__top"><span>Paper Jam / Passport</span><span>Draft</span></div><h3>{form.name}</h3><p>{form.sector} · {form.location}</p><div className="passport__line" /><span className="micro" style={{ color: '#d8c9e0' }}>Will surface</span><div className="check-row" style={{ borderColor: 'rgba(255,255,255,.15)' }}><span>Relevant approvals</span><strong>08</strong></div><div className="check-row" style={{ borderColor: 'rgba(255,255,255,.15)' }}><span>Reusable documents</span><strong>12</strong></div></div></aside></main></Shell></RoleGate>; }

const approvals = [['Business Registration', 'Registrar of Companies', 'Completed'], ['Building Approval', 'Urban Development Authority', 'Completed'], ['Factory Licence', 'Industrial Safety Department', 'In progress'], ['Fire NOC', 'State Fire Services', 'Pending'], ['Pollution Consent', 'Pollution Control Board', 'Pending'], ['Food Safety Licence', 'Food Safety Department', 'Not started']];
function Approvals() { return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Business / Discover" title="Your approval roadmap." copy="Based on your business profile, these approvals apply to you. Start with the one that can move the rest forward." /><section className="timeline">{approvals.map(([name, authority, status], i) => <Link href={name === 'Food Safety Licence' ? '/approval/food-safety' : '/approvals'} className="journey-card surface hoverable" key={name} data-testid={`card-approval-${i}`}><div className="journey-card__main"><span className={`step-dot ${status === 'Completed' ? 'done' : status === 'In progress' ? 'current' : ''}`}>{status === 'Completed' ? <Check size={15} /> : i + 1}</span><div><h3>{name}</h3><p>{authority} · Estimated SLA {i + 2} days</p></div></div><span className={`status ${status === 'Completed' ? 'status--green' : status === 'In progress' ? '' : 'status--amber'}`}>{status}</span></Link>)}</section></main></Shell></RoleGate>; }
function Applications() { const { applicationStatus } = useData(); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Business / In motion" title="Your applications." copy="Every submission, query, and inspection in one calm view." /><div className="section-head"><div><span className="micro">3 active</span><h2>Current applications</h2></div><Link href="/new-application" className="button button--dark" data-testid="link-new-application-page">New application <ArrowRight size={14} /></Link></div><div className="list-stack"><Link href="/tracking" className="application-card surface hoverable" data-testid="card-application-food"><div><span className="micro">Approval</span><h3>Food Safety Licence</h3><p>ABC Foods Pvt. Ltd.</p></div><div><span className="micro">Current stage</span><p>{applicationStatus}</p></div><div><span className="micro">SLA</span><p>2 days remaining</p><span className={`status ${applicationStatus === 'Action Required' ? 'status--amber' : 'status--green'}`}>{applicationStatus}</span></div><ChevronRight size={18} /></Link>{[['Factory Licence', 'Inspection', '6 days remaining'], ['Fire NOC', 'Document Verification', '9 days remaining']].map(([name, stage, sla], i) => <Link href="/inspection" className="application-card surface hoverable" key={name} data-testid={`card-application-${i}`}><div><span className="micro">Approval</span><h3>{name}</h3><p>ABC Foods Pvt. Ltd.</p></div><div><span className="micro">Current stage</span><p>{stage}</p></div><div><span className="micro">SLA</span><p>{sla}</p><span className="status status--green">On track</span></div><ChevronRight size={18} /></Link>)}</div><div className="surface pad" style={{ marginTop: '1.4rem' }}><div className="section-head"><div><span className="micro">One thing needs you</span><h2>Factory layout query</h2></div><Link href="/queries" className="button button--soft" data-testid="link-resolve-query">Resolve query <ArrowRight size={14} /></Link></div><p className="muted-copy">The Food Safety Department requested an updated signature.</p></div></main></Shell></RoleGate>; }
function ApprovalDetail() { return <RoleGate allowed="business"><Shell role="business"><main className="page"><Link href="/approvals" className="eyebrow" data-testid="link-detail-back"><ArrowLeft size={14} /> Approval roadmap</Link><PageIntro eyebrow="Required for your business" title="Food Safety Licence" copy="A clear view of why this approval exists and exactly what will make the application move." /><section className="surface pad"><div className="callout"><CircleCheck size={20} /><div><h3>Why is this required?</h3><p>This approval applies because your business operates in the food-processing sector.</p></div></div><div className="stats-grid" style={{ marginTop: '1.8rem' }}><div><span className="micro">Business condition</span><p><b>Food Processing</b></p></div><div><span className="micro">Location</span><p><b>Gujarat</b></p></div><div><span className="micro">Project type</span><p><b>Manufacturing</b></p></div><div><span className="micro">Regulatory basis</span><p><b>FSS Act, 2006</b></p></div></div><div style={{ marginTop: '2rem' }}><div className="section-head"><div><span className="micro">Required documents</span><h2>3 of 4 available</h2></div><span className="status status--amber">1 missing</span></div><div className="check-list">{['Business Registration', 'Land Document', 'Project Report', 'Food Safety Declaration'].map((doc, i) => <div className="check-row" key={doc}><span><span className={`check ${i === 3 ? 'pending' : ''}`}>{i === 3 ? '○' : '✓'}</span> {doc}</span><span className={i === 3 ? 'status status--amber' : 'micro'}>{i === 3 ? 'Add document' : 'Verified'}</span></div>)}</div></div><Link href="/readiness" className="button button--dark" style={{ marginTop: '1.6rem' }} data-testid="link-prepare-application">Prepare application <ArrowRight size={14} /></Link></section></main></Shell></RoleGate>; }
function Readiness() { const [fixed, setFixed] = useState(false); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Food Safety Licence / Prepare" title="Is your application ready?" copy="A last calm check before it leaves your desk." /><section className="surface pad soft-glow"><div className="readiness-layout"><div className="readiness-ring"><div><strong>{fixed ? '100' : '92'}%</strong><small>ready to submit</small></div></div><div><span className="micro">Readiness check</span><h2>{fixed ? 'Everything looks good.' : 'One small thing left.'}</h2><p className="muted-copy">{fixed ? 'Your application can move to the department.' : 'We found one issue before the department has to.'}</p></div></div></section><section className="surface pad" style={{ marginTop: '1rem' }}><div className="check-list">{['Business information complete', 'Required documents uploaded', 'Document names match', 'Address verified'].map((item) => <div className="check-row" key={item}><span><span className="check">✓</span> {item}</span></div>)}<div className="check-row"><span><span className={`check ${fixed ? '' : 'pending'}`}>{fixed ? '✓' : '!'}</span> Factory layout signature {fixed ? 'added' : 'missing'}</span></div></div></section>{!fixed ? <div className="callout" style={{ marginTop: '1rem' }}><AlertCircle size={21} /><div style={{ flex: 1 }}><h3>One thing is blocking submission.</h3><p>Factory Layout needs a signature before the department can accept it.</p></div><button className="button button--dark" onClick={() => setFixed(true)} data-testid="button-fix-document">Fix document <ArrowRight size={14} /></button></div> : <div className="surface pad action-row" style={{ marginTop: '1rem' }}><span className="status status--green">Ready to submit</span><Link href="/tracking" className="button button--dark" data-testid="link-submit-application">Submit application <ArrowRight size={14} /></Link></div>}</main></Shell></RoleGate>; }
function Tracking() { const { applicationStatus } = useData(); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Application / Food Safety Licence" title="Track your application." copy="No black box. See where it is, who has it, and what happens next." /><div className="detail-grid"><section className="surface pad"><div className="timeline">{[['Submitted', '18 Sep 2026', 'done'], ['Document Verification', '19 Sep 2026', 'done'], ['Department Review', applicationStatus, 'active'], ['Inspection', 'Awaiting schedule', 'pending'], ['Approval', 'Not started', 'pending']].map(([name, date, state], i) => <div className="timeline-item" key={name}><span className={`timeline-dot ${state}`}>{state === 'done' ? <Check size={13} /> : i + 1}</span><div className="timeline-content"><h3>{name} {state === 'active' && <span className="status">Current</span>}</h3><p>{date} · Food Safety Department</p></div></div>)}</div></section><aside className="soft-glow"><div className="surface pad"><span className="micro">Department review</span><h2 className="big-inline-number">11 <small>days elapsed</small></h2><div className="metric-row"><span>Expected SLA</span><strong>15 days</strong></div><div className="progress-track"><div className="progress-fill" style={{ width: '73%' }} /></div><span className="status status--green" style={{ marginTop: '1rem' }}>On track</span></div></aside></div></main></Shell></RoleGate>; }
function Queries() { const [resolved, setResolved] = useState(false); return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Application / Action required" title="Action required." copy="A department asked for one clear change. Resolve it here and keep your application moving." /><section className="soft-glow"><div className="surface pad"><span className={`status ${resolved ? 'status--green' : 'status--amber'}`}>{resolved ? 'Sent to department' : 'Needs your reply'}</span><h2>Department requested an updated factory layout.</h2><div className="check-list"><div className="check-row"><span className="micro">Requested by</span><strong>Food Safety Department</strong></div><div className="check-row"><span className="micro">Due</span><strong>28 Sep 2026</strong></div></div>{!resolved ? <button className="button button--dark" onClick={() => setResolved(true)} data-testid="button-upload-query"><Upload size={14} /> Upload updated document</button> : <div className="callout"><Check size={18} /><div><h3>Updated document uploaded.</h3><p>The department has been notified and your query is back in their queue.</p></div></div>}</div></section></main></Shell></RoleGate>; }
function Inspection() { const [selected, setSelected] = useState('24 Sep · 10:00 AM'); const [confirmed, setConfirmed] = useState(false); const slots = ['24 Sep · 10:00 AM', '24 Sep · 2:00 PM', '25 Sep · 11:00 AM']; return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Food Safety Licence / Next step" title="Inspection." copy="Choose a time that works for your factory team." /><section className="surface pad"><div className="section-head"><div><span className="micro">Factory inspection</span><h2>{confirmed ? 'Inspection scheduled' : 'Schedule required'}</h2></div><span className={`status ${confirmed ? 'status--green' : 'status--amber'}`}>{confirmed ? selected : 'Pending'}</span></div><div className="slot-grid">{slots.map((slot) => { const [date, time] = slot.split(' · '); return <button className={`slot ${selected === slot ? 'selected' : ''}`} key={slot} onClick={() => setSelected(slot)} data-testid={`button-business-slot-${time.replaceAll(' ', '-').toLowerCase()}`}><strong>{date}</strong><span>{time}</span></button>; })}</div><button className="button button--dark" style={{ marginTop: '1.3rem' }} onClick={() => setConfirmed(true)} data-testid="button-confirm-inspection">{confirmed ? 'Inspection confirmed' : 'Confirm inspection'} <ArrowRight size={14} /></button></section></main></Shell></RoleGate>; }
function Compliance() { return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="After approval" title="Stay compliant." copy="Everything you need to renew and maintain after approval, without the calendar anxiety." /><div className="stats-grid"><div className="surface stat"><span className="micro">Renewals</span><h3>2</h3><p>upcoming</p></div><div className="surface stat"><span className="micro">Obligations</span><h3>5</h3><p>active</p></div><Link href="/compliance/guardian" className="surface stat hoverable" data-testid="card-compliance-changes"><span className="micro">Regulation changes</span><h3>1</h3><p>affecting you</p></Link><div className="surface stat"><span className="micro">Documents</span><h3>12</h3><p>verified</p></div></div><div className="layout" style={{ marginTop: '2rem' }}><section className="surface pad"><span className="micro">Coming up</span><h2>Keep an eye on these.</h2><div className="list-stack"><div className="journey-card"><div><h3>Fire NOC</h3><p>Renewal · State Fire Services</p></div><span className="status status--amber">18 days</span></div><div className="journey-card"><div><h3>Factory Licence</h3><p>Renewal · Industrial Safety</p></div><span className="status">43 days</span></div></div></section><aside className="soft-glow"><div className="surface pad"><span className="micro">Your compliance pulse</span><h2>Quietly on track.</h2><p className="muted-copy">One regulation change needs a closer look.</p><Link href="/compliance/guardian" className="button button--dark" data-testid="link-review-compliance">Review change <ArrowRight size={14} /></Link></div></aside></div></main></Shell></RoleGate>; }
function Guardian() { return <RoleGate allowed="business"><Shell role="business"><main className="page"><PageIntro eyebrow="Compliance Guardian" title="Something changed." copy="New regulation may affect your business. We’ve made the change legible before it becomes urgent." /><section className="soft-glow"><div className="surface pad"><span className="status status--amber">Needs review</span><h2>New regulation may affect your business.</h2><div className="form-grid" style={{ margin: '2rem 0' }}><div><span className="micro">Regulation</span><p><b>Updated Pollution Control Requirement</b></p></div><div><span className="micro">Effective</span><p><b>15 Oct 2026</b></p></div><div><span className="micro">Impact</span><p><b>Updated document may be required</b></p></div></div><div className="callout"><Sparkles size={19} /><div><h3>What you need to do</h3><p>Review updated requirement, upload revised document, complete compliance update.</p></div></div><button className="button button--dark" onClick={() => window.alert('Requirement marked for review.')} data-testid="button-review-change">Review change <ArrowRight size={14} /></button></div></section></main></Shell></RoleGate>; }
function NewApplication() { return <RoleGate allowed="business"><Shell role="business"><main className="page layout"><section><PageIntro eyebrow="Start a new journey" title="What are you applying for?" copy="Choose the approval and we’ll carry your passport into a ready-to-submit application." /><div className="surface pad list-stack"><Link href="/approval/food-safety" className="journey-card" data-testid="link-select-food-safety"><div className="journey-card__main"><span className="step-dot current"><FileText size={15} /></span><div><h3>Food Safety Licence</h3><p>Food Safety Department · 15 day SLA</p></div></div><ArrowRight size={17} /></Link><div className="journey-card muted-row"><div className="journey-card__main"><span className="step-dot"><FileText size={15} /></span><div><h3>Factory Licence</h3><p>Already in progress</p></div></div><span className="micro">In passport</span></div></div></section><aside className="soft-glow"><div className="passport"><div className="passport__top"><span>Ready when you are</span><Sparkles size={15} /></div><h3>Start with<br />what you know.</h3><p>Your verified documents will be suggested as you go.</p></div></aside></main></Shell></RoleGate>; }
function Profile({ role }: { role: Role }) { return <Shell role={role}><main className="page"><PageIntro eyebrow={`${role} / Account`} title="Your profile." copy="A small, clear view of the account behind this workspace." /><section className="surface pad profile-panel"><div className="avatar avatar--large">{role === 'admin' ? 'PJ' : role === 'department' ? 'OP' : 'AR'}</div><div><span className="micro">Signed in as</span><h2>{role === 'admin' ? 'Paper Jam admin' : role === 'department' ? 'Officer Patel' : 'Arjun Rao'}</h2><p className="muted-copy">{role === 'admin' ? 'System administrator' : role === 'department' ? 'Food Safety Department' : 'ABC Foods Pvt. Ltd.'}</p></div></section></main></Shell>; }

const officerApps = [{ company: 'ABC Foods Pvt. Ltd.', licence: 'Food Safety Licence', stage: 'Department Review', sla: '2 days remaining', status: 'At Risk' }, { company: 'GreenTech Industries', licence: 'Factory Licence', stage: 'Inspection', sla: '5 days remaining', status: 'On Track' }, { company: 'Mitra Textiles', licence: 'Pollution Consent', stage: 'Document Verification', sla: '9 days remaining', status: 'On Track' }];
function Officer() { return <RoleGate allowed="department"><Shell role="department"><main className="page"><PageIntro eyebrow="Department workspace" title="Good morning, Officer." copy="Here’s what needs your attention today." /><div className="stats-grid stats-grid--five">{[['New applications', '24'], ['Under review', '18'], ['Queries', '7'], ['Inspections', '5'], ['SLA at risk', '3']].map(([label, value], i) => <div className="surface stat" key={label}><span className="micro">{label}</span><h3>{value}</h3><p>{i === 4 ? <span className="status status--red">Needs attention</span> : 'today'}</p></div>)}</div><section style={{ marginTop: '2.3rem' }}><div className="section-head"><div><span className="micro">Queue / priority first</span><h2>Applications needing attention</h2></div><Link href="/officer/sla" className="button button--light" data-testid="link-sla-monitor">SLA monitor <ArrowRight size={14} /></Link></div><div className="list-stack">{officerApps.map((app, i) => <div className="application-card surface hoverable" key={app.company} data-testid={`card-officer-application-${i}`}><div><span className="micro">Applicant</span><h3>{app.company}</h3><p>{app.licence}</p></div><div><span className="micro">Stage</span><p>{app.stage}</p><p>Submitted 18 Sep 2026</p></div><div><span className="micro">SLA</span><p>{app.sla}</p><span className={`status ${app.status === 'At Risk' ? 'status--red' : 'status--green'}`}>{app.status}</span></div><Link href="/officer/application" className="button button--dark" data-testid={`link-review-officer-${i}`}>{i === 0 ? 'Review' : 'Open'} <ArrowRight size={14} /></Link></div>)}</div></section></main></Shell></RoleGate>; }
function OfficerApplications() { return <Officer />; }
function QueryModal({ onClose }: { onClose: () => void }) { const { setApplicationStatus, setQuerySent, toast } = useData(); const [text, setText] = useState('Factory layout is missing the required signature.'); const [due, setDue] = useState('2026-09-28'); return <div className="modal-backdrop"><section className="modal surface pad" role="dialog" aria-modal="true"><div className="section-head"><div><span className="micro">ABC Foods Pvt. Ltd.</span><h2>Request additional information</h2></div><button className="icon-button" onClick={onClose} aria-label="Close query modal" data-testid="button-close-query"><X size={15} /></button></div><div className="form-stack"><div className="field"><label>What needs to be corrected?</label><textarea rows={4} value={text} onChange={(e) => setText(e.target.value)} data-testid="textarea-query" /></div><div className="field"><label>Due date</label><input type="date" value={due} onChange={(e) => setDue(e.target.value)} data-testid="input-query-due-date" /></div><div className="modal-actions"><button className="button button--light" onClick={onClose} data-testid="button-cancel-query">Cancel</button><button className="button button--dark" onClick={() => { setApplicationStatus('Action Required'); setQuerySent(true); toast('Query sent to ABC Foods.'); onClose(); }} data-testid="button-send-query">Send query <ArrowRight size={14} /></button></div></div></section></div>; }
function OfficerReview() { const { applicationStatus, querySent, setApplicationStatus } = useData(); const [tab, setTab] = useState('Overview'); const [queryOpen, setQueryOpen] = useState(false); const [inspectionDone, setInspectionDone] = useState(false); const tabs = ['Overview', 'Documents', 'Queries', 'Inspection']; return <RoleGate allowed="department"><Shell role="department"><main className="page"><Link href="/officer" className="eyebrow" data-testid="link-officer-back"><ArrowLeft size={14} /> Officer queue</Link><PageIntro eyebrow="Application review" title="ABC Foods Pvt. Ltd." copy="Food Safety Licence · Submitted 18 Sep 2026" /><div className="detail-grid"><section className="surface pad"><div className="review-heading"><div><span className="micro">Food Safety Licence</span><h2>Application review</h2></div><span className={`status ${applicationStatus === 'Action Required' ? 'status--amber' : 'status--purple'}`}>{applicationStatus.toUpperCase()}</span></div><div className="tabs">{tabs.map((item) => <button className={`tab ${tab === item ? 'active' : ''}`} key={item} onClick={() => setTab(item)} data-testid={`tab-${item.toLowerCase()}`}>{item}</button>)}</div>{tab === 'Overview' && <div className="review-overview"><div className="form-grid">{[['Business', 'ABC Foods Pvt. Ltd.'], ['Sector', 'Food Processing'], ['Location', 'Ahmedabad, Gujarat'], ['Investment', '₹5 Cr'], ['Employees', '120']].map(([label, value]) => <div key={label}><span className="micro">{label}</span><p><b>{value}</b></p></div>)}</div><DocumentList /></div>}{tab === 'Documents' && <DocumentList detailed />}{tab === 'Queries' && <div className="empty-panel"><AlertCircle size={22} /><h3>{querySent ? 'Query is with the business.' : 'No previous queries.'}</h3><p>{querySent ? 'The applicant has been asked to correct the factory layout.' : 'Raise a query when an application needs a correction.'}</p></div>}{tab === 'Inspection' && <div className="empty-panel"><CalendarDays size={22} /><h3>{inspectionDone ? 'Inspection scheduled.' : 'No inspection scheduled.'}</h3><p>{inspectionDone ? 'The business will see the confirmed slot in its application timeline.' : 'Choose a slot to move this application forward.'}</p><Link href="/officer/inspections" className="button button--soft" data-testid="link-review-inspection">Open inspection scheduling <ArrowRight size={14} /></Link></div>}</section><aside className="soft-glow"><div className="surface pad"><span className="micro">Application status</span><h2 className="status-heading">{applicationStatus}</h2><div className="metric-row"><span>SLA</span><strong>2 days remaining</strong></div><div className="progress-track"><div className="progress-fill" style={{ width: applicationStatus === 'Approved' ? '100%' : '76%' }} /></div><div className="form-stack action-stack"><button className="button button--dark" onClick={() => setApplicationStatus('Approved')} data-testid="button-approve-application"><Check size={14} /> Approve</button><button className="button button--light" onClick={() => setQueryOpen(true)} data-testid="button-raise-query"><AlertCircle size={14} /> Raise query</button><Link href="/officer/inspections" className="button button--soft" data-testid="link-officer-schedule-inspection"><CalendarDays size={14} /> Schedule inspection</Link></div></div></aside></div>{queryOpen && <QueryModal onClose={() => setQueryOpen(false)} />}</main></Shell></RoleGate>; }
function DocumentList({ detailed = false }: { detailed?: boolean }) { return <div style={{ marginTop: '1.8rem' }}><div className="section-head"><div><span className="micro">Documents</span><h2>{detailed ? 'Verified documents' : 'Complete application'}</h2></div><span className="status status--green">4 verified</span></div><div className="check-list">{['Company Registration', 'Land Document', 'Project Report', 'Food Safety Declaration'].map((doc, i) => <div className="check-row" key={doc}><span><span className="check">✓</span> {doc}</span><div className="row-actions"><span className="micro">Verified</span><button className="button button--light tiny-button" data-testid={`button-view-document-${i}`}><Eye size={12} /> View</button></div></div>)}</div></div>; }
function OfficerInspections() { const { inspectionSlot, setInspectionSlot, setApplicationStatus, toast } = useData(); const [selected, setSelected] = useState(inspectionSlot || '24 Sep · 10:00 AM'); const [confirmed, setConfirmed] = useState(Boolean(inspectionSlot)); const slots = ['24 Sep · 10:00 AM', '24 Sep · 2:00 PM', '25 Sep · 11:00 AM']; return <RoleGate allowed="department"><Shell role="department"><main className="page"><PageIntro eyebrow="Department / Next action" title="Schedule Inspection" copy="Choose a clear time for ABC Foods and keep the application moving." /><section className="surface pad inspection-panel"><div className="section-head"><div><span className="micro">ABC Foods Pvt. Ltd.</span><h2>Factory Inspection</h2></div><span className={`status ${confirmed ? 'status--green' : 'status--amber'}`}>{confirmed ? 'Inspection Scheduled' : 'Awaiting slot'}</span></div><div className="slot-grid">{slots.map((slot) => { const [date, time] = slot.split(' · '); return <button className={`slot ${selected === slot ? 'selected' : ''}`} key={slot} onClick={() => setSelected(slot)} data-testid={`button-slot-${time.replaceAll(' ', '-').toLowerCase()}`}><CalendarDays size={15} /><strong>{date}</strong><span>{time}</span></button>; })}</div><button className="button button--dark" style={{ marginTop: '1.4rem' }} onClick={() => { setInspectionSlot(selected); setConfirmed(true); setApplicationStatus('Inspection Scheduled'); toast('Inspection confirmed for ABC Foods.'); }} data-testid="button-confirm-department-inspection">{confirmed ? 'Inspection confirmed' : 'Confirm inspection'} <ArrowRight size={14} /></button></section></main></Shell></RoleGate>; }
function SLA() { const data = [['Document verification', '2.1 days', 32], ['Officer review', '3.2 days', 49], ['Inspection', '5.8 days', 88], ['Query resolution', '1.3 days', 20]]; return <RoleGate allowed="department"><Shell role="department"><main className="page"><PageIntro eyebrow="Department intelligence" title="Where approvals get stuck." copy="Monitor processing time across departments." /><div className="layout"><section className="surface pad soft-glow"><span className="micro">Average processing time</span><div className="big-number">12.4 <small>days</small></div><div className="bar-chart" style={{ marginTop: '2rem' }}>{data.map(([label, value, width]) => <div className="chart-item" key={label}><span>{label}</span><div className="chart-line"><span style={{ width: `${width}%` }} /></div><strong>{value}</strong></div>)}</div></section><aside><div className="callout callout--purple"><Sparkles size={20} /><div><h3>Inspection Scheduling</h3><p>Largest current bottleneck, at 5.8 days on average.</p></div></div><Link href="/officer/inspections" className="button button--dark" style={{ marginTop: '1rem' }} data-testid="link-improve-inspections">Open inspection workflow <ArrowRight size={14} /></Link></aside></div></main></Shell></RoleGate>; }
function OfficerAnalytics() { return <RoleGate allowed="department"><Shell role="department"><main className="page"><PageIntro eyebrow="Department / Analytics" title="Approval performance." copy="A small set of signals for the decisions that matter." /><div className="stats-grid"><div className="surface stat"><span className="micro">Applications processed</span><h3>248</h3><p>this quarter</p></div><div className="surface stat"><span className="micro">Average processing</span><h3>12.4</h3><p>days</p></div><div className="surface stat"><span className="micro">Within SLA</span><h3>87%</h3><p>of applications</p></div><div className="surface stat"><span className="micro">Pending</span><h3>31</h3><p>in queue</p></div></div><section className="surface pad analytics-panel"><span className="micro">Processing by stage</span><h2>Application volume</h2><div className="bar-chart">{[['Document verification', 74], ['Officer review', 58], ['Inspection', 42], ['Approval', 81]].map(([label, width]) => <div className="chart-item" key={label}><span>{label}</span><div className="chart-line"><span style={{ width: `${width}%` }} /></div><strong>{width}%</strong></div>)}</div></section></main></Shell></RoleGate>; }

function AdminShellPage({ children, title, eyebrow, copy, action }: { children: ReactNode; title: string; eyebrow: string; copy: string; action?: ReactNode }) { return <RoleGate allowed="admin"><Shell role="admin"><main className="page"><PageIntro eyebrow={eyebrow} title={title} copy={copy}>{action}</PageIntro>{children}</main></Shell></RoleGate>; }
function AdminOverview() { return <AdminShellPage eyebrow="Platform / Overview" title="Paper Jam overview." copy="See how the approval ecosystem is performing."><div className="stats-grid"><Metric label="Total businesses" value="1,248" hint="active workspaces" /><Metric label="Active applications" value="326" hint="moving today" /><Metric label="Approvals processed" value="4,821" hint="this quarter" /><Metric label="SLA at risk" value="42" hint="needs attention" danger /></div><section className="admin-overview-grid"><div className="surface pad"><div className="section-head"><div><span className="micro">System overview</span><h2>The platform at a glance.</h2></div><Activity size={18} /></div><div className="mini-stat-grid">{[['Departments', '18'], ['Active regulations', '142'], ['Pending queries', '76'], ['Inspections', '34']].map(([label, value]) => <div className="mini-stat" key={label}><span className="micro">{label}</span><strong>{value}</strong></div>)}</div></div><div className="soft-glow"><div className="surface pad"><span className="micro">This week</span><h2>Steady, with one pressure point.</h2><p className="muted-copy">Pollution Control is taking longer than the network average. The signal is ready for a closer look.</p><Link href="/admin/bottlenecks" className="button button--dark" data-testid="link-admin-bottlenecks">View bottlenecks <ArrowRight size={14} /></Link></div></div></section></AdminShellPage>; }
function Metric({ label, value, hint, danger = false }: { label: string; value: string; hint: string; danger?: boolean }) { return <div className="surface stat"><span className="micro">{label}</span><h3>{value}</h3><p>{danger ? <span className="status status--red">{hint}</span> : hint}</p></div>; }
function AdminDepartments() { const departments = [['Department of Industries', '428', '11.2 days'], ['Pollution Control Department', '312', '16.2 days'], ['Fire Department', '284', '9.8 days'], ['Food Safety Department', '397', '12.4 days'], ['Labour Department', '198', '8.4 days']]; return <AdminShellPage eyebrow="Admin / Network" title="Departments" copy="A clear view of the teams powering the approval network."><div className="admin-card-grid">{departments.map(([name, apps, sla], i) => <article className="surface pad admin-dept-card" key={name}><div className="role-card__top"><span className="status status--green">Active</span><Building2 size={18} /></div><h2>{name}</h2><div className="metric-row"><span>Applications</span><strong>{apps}</strong></div><div className="metric-row"><span>Average SLA</span><strong>{sla}</strong></div><Link href="/admin/bottlenecks" className="button button--light" data-testid={`link-view-department-${i}`}>View department <ArrowRight size={14} /></Link></article>)}</div></AdminShellPage>; }
function AdminUsers() { const [users, setUsers] = useState([{ name: 'ABC Foods Pvt. Ltd.', role: 'Business', detail: 'Business account', active: true }, { name: 'Raj Patel', role: 'Department Officer', detail: 'Food Safety', active: true }, { name: 'Nisha Shah', role: 'Department Officer', detail: 'Pollution Control', active: false }, { name: 'Paper Jam Admin', role: 'Admin', detail: 'System administrator', active: true }]); const [filter, setFilter] = useState('All'); const visible = filter === 'All' ? users : users.filter((u) => u.role.includes(filter)); return <AdminShellPage eyebrow="Admin / People" title="People using Paper Jam." copy="Keep access clear, visible, and easy to manage."><div className="tabs admin-tabs">{['All', 'Business', 'Department', 'Admin'].map((item) => <button className={`tab ${filter === item ? 'active' : ''}`} key={item} onClick={() => setFilter(item)} data-testid={`button-filter-users-${item.toLowerCase()}`}>{item}</button>)}</div><div className="admin-user-grid">{visible.map((user, i) => <article className="surface pad user-card" key={user.name}><div className="user-card__top"><div className="avatar">{user.name.split(' ').map((x) => x[0]).slice(0, 2).join('')}</div><span className={`status ${user.active ? 'status--green' : 'status--amber'}`}>{user.active ? 'Active' : 'Inactive'}</span></div><h2>{user.name}</h2><p className="muted-copy">{user.role} · {user.detail}</p><div className="metric-row"><span>Last activity</span><strong>{i === 2 ? '20 Sep 2026' : 'Today'}</strong></div><div className="row-actions"><button className="button button--light tiny-button" data-testid={`button-view-user-${i}`}><Eye size={12} /> View</button><button className={`button ${user.active ? 'button--danger' : 'button--soft'} tiny-button`} onClick={() => setUsers(users.map((item) => item.name === user.name ? { ...item, active: !item.active } : item))} data-testid={`button-toggle-user-${i}`}>{user.active ? 'Deactivate' : 'Activate'}</button></div></article>)}</div></AdminShellPage>; }
function AdminRegulations() { const [message, setMessage] = useState(''); const regs = [['Food Safety Regulations', 'Version 3.2', '12 Sep 2026'], ['Pollution Control Requirements', 'Version 5.1', '18 Sep 2026'], ['Factory Safety Rules', 'Version 2.4', '20 Sep 2026']]; return <AdminShellPage eyebrow="Admin / Knowledge" title="Regulatory knowledge." copy="Manage the rules that power approval decisions." action={<button className="button button--dark" onClick={() => setMessage('New regulation version upload ready.')} data-testid="button-upload-regulation"><Upload size={14} /> Upload new version</button>}><div className="admin-card-grid">{regs.map(([name, version, date], i) => <article className="surface pad regulation-card" key={name}><div className="role-card__top"><span className="micro">Active regulation</span><ScrollText size={18} /></div><h2>{name}</h2><p className="muted-copy">{version} · Updated {date}</p><div className="row-actions"><button className="button button--light tiny-button" onClick={() => setMessage(`${name} opened for review.`)} data-testid={`button-view-regulation-${i}`}>View regulation</button><Link href="/admin/regulation-change" className="button button--soft tiny-button" data-testid={`link-update-regulation-${i}`}>Update <ArrowRight size={12} /></Link></div></article>)}</div>{message && <div className="toast-note" role="status">{message}<button onClick={() => setMessage('')} aria-label="Dismiss notification" data-testid="button-dismiss-toast"><X size={13} /></button></div>}</AdminShellPage>; }
function AdminRegulationChange() { const [reviewed, setReviewed] = useState(false); return <AdminShellPage eyebrow="Admin / Change control" title="Regulation change detected." copy="Understand the impact before a new requirement reaches a business."><section className="surface pad regulation-change"><div className="version-compare"><div><span className="micro">Previous version</span><h2>Pollution Control Requirement</h2><span className="status">Version 5.0</span></div><ArrowRight size={20} /><div><span className="micro">New version</span><h2>Pollution Control Requirement</h2><span className="status status--green">Version 5.1</span></div></div><div className="form-grid impact-grid"><div><span className="micro">Affected sector</span><p><b>Food Processing</b></p></div><div><span className="micro">Affected approval</span><p><b>Pollution Consent</b></p></div><div><span className="micro">Affected businesses</span><p><b>38</b></p></div></div>{reviewed ? <div className="callout callout--purple"><CheckCircle2 size={19} /><div><h3>Impact review recorded.</h3><p>The change is ready to surface in Compliance Guardian.</p></div></div> : <button className="button button--dark" onClick={() => setReviewed(true)} data-testid="button-review-impact">Review impact <ArrowRight size={14} /></button>}</section></AdminShellPage>; }
function AdminBottlenecks() { const data = [['Food Safety', '12.4 days', 68], ['Pollution Control', '16.2 days', 92], ['Fire Department', '9.8 days', 54]]; return <AdminShellPage eyebrow="Admin / Performance" title="Where the system gets stuck." copy="A simple view of the moments that deserve intervention."><div className="stats-grid"><Metric label="Total applications" value="326" hint="active" /><Metric label="At risk" value="42" hint="needs attention" danger /><Metric label="Breached SLA" value="17" hint="this month" danger /></div><section className="surface pad bottleneck-panel"><span className="micro">Department bottlenecks</span><h2>Average processing time</h2><div className="bar-chart">{data.map(([name, value, width]) => <div className="chart-item" key={name}><span>{name}</span><div className="chart-line"><span style={{ width: `${width}%` }} /></div><strong>{value}</strong></div>)}</div></section><div className="callout callout--purple"><Sparkles size={19} /><div><h3>Pollution Control has the highest average processing time.</h3><p>Review inspection scheduling and query resolution before adding more volume.</p></div></div></AdminShellPage>; }
function AdminAudit() { const events = [['Raj Patel', 'Updated Pollution Regulation', '23 Sep 2026 · 10:42 AM'], ['Paper Jam system', 'Application approved', '23 Sep 2026 · 09:18 AM'], ['Nisha Shah', 'Document verified', '22 Sep 2026 · 16:04 PM'], ['Raj Patel', 'Query raised', '21 Sep 2026 · 11:26 AM']]; return <AdminShellPage eyebrow="Admin / Accountability" title="Everything has a history." copy="A clear timeline of the actions shaping the platform."><section className="surface pad"><div className="timeline">{events.map(([user, action, date], i) => <div className="timeline-item" key={action}><span className={`timeline-dot ${i === 0 ? 'active' : 'done'}`}>{i === 0 ? <History size={13} /> : <Check size={13} />}</span><div className="timeline-content"><h3>{action}</h3><p>{user} · {date}</p><span className="micro">Object / Paper Jam platform</span></div></div>)}</div></section></AdminShellPage>; }
function AdminSettings() { const [selected, setSelected] = useState('Departments'); const sections = ['Departments', 'Roles & Permissions', 'Approval Rules', 'Regulations', 'Notifications', 'System Configuration']; return <AdminShellPage eyebrow="Admin / Control room" title="System settings." copy="Keep the platform’s operating principles close and clear."><div className="settings-layout"><div className="surface pad settings-menu">{sections.map((section) => <button className={`settings-item ${selected === section ? 'selected' : ''}`} key={section} onClick={() => setSelected(section)} data-testid={`button-settings-${section.toLowerCase().replaceAll(' ', '-')}`}><span>{section}</span><ChevronRight size={15} /></button>)}</div><section className="surface pad"><span className="micro">Selected setting</span><h2>{selected}</h2><p className="muted-copy">Manage {selected.toLowerCase()} for Paper Jam. Changes are saved locally in this demo.</p><button className="button button--dark" onClick={() => window.alert(`${selected} settings opened.`)} data-testid="button-open-settings">Open settings <ArrowRight size={14} /></button></section></div></AdminShellPage>; }

function Router() { return <Switch><Route path="/" component={Home} /><Route path="/login" component={Login} /><Route path="/signup" component={Signup} /><Route path="/onboarding" component={Onboarding} /><Route path="/dashboard" component={Dashboard} /><Route path="/approvals" component={Approvals} /><Route path="/approval/food-safety" component={ApprovalDetail} /><Route path="/readiness" component={Readiness} /><Route path="/applications" component={Applications} /><Route path="/tracking" component={Tracking} /><Route path="/queries" component={Queries} /><Route path="/inspection" component={Inspection} /><Route path="/compliance" component={Compliance} /><Route path="/compliance/guardian" component={Guardian} /><Route path="/new-application" component={NewApplication} /><Route path="/profile" component={() => <Profile role="business" />} /><Route path="/officer" component={Officer} /><Route path="/officer/applications" component={OfficerApplications} /><Route path="/officer/application" component={OfficerReview} /><Route path="/officer/inspections" component={OfficerInspections} /><Route path="/officer/sla" component={SLA} /><Route path="/officer/analytics" component={OfficerAnalytics} /><Route path="/officer/profile" component={() => <Profile role="department" />} /><Route path="/sla" component={SLA} /><Route path="/admin" component={AdminOverview} /><Route path="/admin/departments" component={AdminDepartments} /><Route path="/admin/users" component={AdminUsers} /><Route path="/admin/regulations" component={AdminRegulations} /><Route path="/admin/regulation-change" component={AdminRegulationChange} /><Route path="/admin/bottlenecks" component={AdminBottlenecks} /><Route path="/admin/audit" component={AdminAudit} /><Route path="/admin/settings" component={AdminSettings} /><Route path="/admin/profile" component={() => <Profile role="admin" />} /><Route component={NotFound} /></Switch>; }
function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function App() { const [role, setRole] = useState<Role | null>(null); const [applicationStatus, setApplicationStatus] = useState<AppStatus>('Under Review'); const [querySent, setQuerySent] = useState(false); const [inspectionSlot, setInspectionSlot] = useState(''); const [notice, setNotice] = useState(''); const toast = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 3200); }; const data = { applicationStatus, setApplicationStatus, querySent, setQuerySent, inspectionSlot, setInspectionSlot, toast }; return <QueryClientProvider client={queryClient}><TooltipProvider><AuthContext.Provider value={{ role, setRole }}><DataContext.Provider value={data}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><RoutedErrorBoundary><Router /></RoutedErrorBoundary></WouterRouter>{notice && <div className="toast-note" role="status" data-testid="toast-notice">{notice}</div>}</DataContext.Provider></AuthContext.Provider></TooltipProvider><Toaster /></QueryClientProvider>; }
export default App;